-- DaVinci Resolve: build the edit timeline for a video-from-script project.
-- Generated by make_resolve_project.py. Run it inside Resolve:
--   Workspace > Scripts > Build timeline - <title>
-- Creates/opens the project, imports scene clips, narration and subtitles, lays them
-- out with cross-dissolves and scene markers, presets the Deliver page.
-- It does NOT render: review, edit and export from Resolve.
-- A log is written next to this script's source (see M.log_path).

local M = __MANIFEST__

-- Resolve 21.2+ runs menu scripts without the `io` library: then the log only goes to
-- Workspace > Console, and errors are re-raised so they land in Resolve's ResolveDebug.txt.
local logf = (type(io) == "table" and io.open) and io.open(M.log_path, "w") or nil
local function say(...)
  local t = {}
  for i = 1, select("#", ...) do t[i] = tostring(select(i, ...)) end
  local s = "[video-from-script] " .. table.concat(t, " ")
  print(s)
  if logf then logf:write(s .. "\n"); logf:flush() end
end

-- Resolve's Lua lists are not always {1 = obj, 2 = obj}: some calls return
-- {obj = index}. These helpers accept both shapes and only yield real objects.
local function is_obj(x) return type(x) == "userdata" or type(x) == "table" end

local function objects(list)
  local out = {}
  if type(list) ~= "table" then return out end
  for k, v in pairs(list) do
    if is_obj(v) then out[#out + 1] = v elseif is_obj(k) then out[#out + 1] = k end
  end
  return out
end

local function first(list) return objects(list)[1] end

local function set_settings(obj, tbl)
  local ok = true
  for k, v in pairs(tbl) do
    local r = obj:SetSetting(k, v)
    say("setting", k, "=", v, "->", r)
    ok = ok and r
  end
  return ok
end

local function main()
  local r = resolve or Resolve()
  if not r then error("STOP: cannot reach DaVinci Resolve"); return end
  say("product:", r:GetProductName(), r:GetVersionString())
  local pm = r:GetProjectManager()

  -- 1. project: frame rate/resolution must be set before its first timeline exists
  local project = pm:CreateProject(M.project)
  if project then
    set_settings(project, { timelineFrameRate = tostring(M.fps),
                            timelineResolutionWidth = tostring(M.width),
                            timelineResolutionHeight = tostring(M.height) })
  else
    project = pm:LoadProject(M.project)
    if not project then error("STOP: could not create or load project " .. M.project); return end
    say("project exists; its frame rate is", project:GetSetting("timelineFrameRate"), "(needs", M.fps, ")")
  end
  say("project:", project:GetName())

  -- 2. media pool layout:  Timelines/ (every build's timeline, side by side)
  --                         Media/v<N>/ (that build's clips, narration, subtitles)
  local mp = project:GetMediaPool()
  local root = mp:GetRootFolder()
  local function subfolder(parent, name)
    for _, f in ipairs(objects(parent:GetSubFolderList())) do
      if f:GetName() == name then return f end
    end
    return mp:AddSubFolder(parent, name)
  end

  -- version number = first "v<N>" not used by an existing timeline
  local taken = {}
  for i = 1, project:GetTimelineCount() do
    local t = project:GetTimelineByIndex(i)
    if t then taken[t:GetName()] = true end
  end
  local version = 1
  local function tl_name_for(v) return "v" .. v .. " · " .. M.build_id end
  while taken[tl_name_for(version)] do version = version + 1 end
  local tl_name = tl_name_for(version)

  local timelines_bin = subfolder(root, "Timelines")
  local media_bin = subfolder(subfolder(root, "Media"), "v" .. version)
  if media_bin then mp:SetCurrentFolder(media_bin) end

  local function imp(path)
    local item = first(mp:ImportMedia({ path }))
    if not item then  -- fallback used by older Resolve builds
      item = first(r:GetMediaStorage():AddItemListToMediaPool({ path }))
    end
    say("import", path, item ~= nil)
    return item
  end

  local scenes = {}
  for i, s in ipairs(M.scenes) do
    scenes[i] = { s = s, clip = imp(s.clip), audio = s.audio and imp(s.audio) or nil }
  end
  local srt_item = M.subtitles and imp(M.subtitles) or nil
  local music_item = M.music and imp(M.music) or nil

  -- 3. timeline
  if timelines_bin then mp:SetCurrentFolder(timelines_bin) end
  local tl = mp:CreateEmptyTimeline(tl_name)
  if not tl then error("STOP: could not create timeline " .. tl_name); return end
  project:SetCurrentTimeline(tl)
  local start = tl:GetStartFrame()
  tl:SetTrackName("video", 1, "Scenes")
  tl:SetTrackName("audio", 1, "Narration")

  local video_items, rec = {}, start
  for _, sc in ipairs(scenes) do
    local s = sc.s
    if sc.clip then
      -- startFrame/endFrame: source frames (clip rate); recordFrame: timeline frames
      local v = first(mp:AppendToTimeline({ { mediaPoolItem = sc.clip, mediaType = 1, trackIndex = 1,
        recordFrame = rec, startFrame = s.handle_frames, endFrame = s.handle_frames + s.frames - 1 } }))
      say("video", s.name, v ~= nil)
      if v then video_items[#video_items + 1] = v end
    end
    if sc.audio then
      local a = first(mp:AppendToTimeline({ { mediaPoolItem = sc.audio, mediaType = 2, trackIndex = 1,
        recordFrame = rec } }))
      say("audio", s.name, a ~= nil)
    end
    tl:AddMarker(rec - start, "Blue", s.name, s.note or "", 1)
    rec = rec + s.timeline_frames
  end

  -- 4. cross-dissolves (clips carry frozen-frame handles for this)
  if M.transition_frames > 0 then
    for i = 1, #video_items - 1 do
      local ok, res = pcall(function()
        return video_items[i]:AddTransition({ type = "Cross Dissolve", category = "simple",
          position = "end", alignment = "center", duration = M.transition_frames })
      end)
      say("transition after scene", i, ok and res ~= nil)
      if not ok then say("AddTransition unavailable; add dissolves by hand (Ctrl+T)"); break end
    end
  end

  -- 5. optional music bed on A2 (M.music_db, default -20 dB under the voice)
  if music_item then
    if tl:GetTrackCount("audio") < 2 then tl:AddTrack("audio", "stereo") end
    tl:SetTrackName("audio", 2, "Music")
    local m = first(mp:AppendToTimeline({ { mediaPoolItem = music_item, mediaType = 2, trackIndex = 2,
      recordFrame = start, startFrame = 0, endFrame = rec - start - 1 } }))
    if m then m:SetProperty("Volume", M.music_db or -20.0) end
    say("music", m ~= nil)
  end

  -- 6. subtitles: always in the media pool, on the timeline only if requested
  if srt_item and M.burn_subtitles then
    tl:AddTrack("subtitle")
    local s = first(mp:AppendToTimeline({ { mediaPoolItem = srt_item, trackIndex = 1, recordFrame = start } }))
    say("subtitles on timeline", s ~= nil)
    if not s then say("Drag subtitles.srt from the Media Pool onto the timeline to add captions.") end
  end

  -- 7. preset the Deliver page (no render is queued)
  pcall(function()
    project:SetCurrentRenderFormatAndCodec("mp4", "H264")
    project:SetRenderSettings({ TargetDir = M.render_dir, CustomName = M.title,
      FormatWidth = M.width, FormatHeight = M.height, FrameRate = M.fps })
  end)

  pm:SaveProject()
  r:OpenPage("edit")
  say(string.format("DONE: timeline '%s', %d scenes, %.1f s. Review, edit, then export from Deliver.",
    tl_name, #scenes, (rec - start) / M.fps))
end

local ok, err = pcall(main)
if not ok then say("ERROR:", err) end
if logf then logf:close() end
if not ok then error("video-from-script: " .. tostring(err)) end
